{
  "tool": "aikido_login",
  "description": "Starts the Aikido sign-in flow. Returns a sign-in URL for the user to open in their browser, OR confirms the user is already signed in. WHEN TO CALL THIS TOOL - The user explicitly asks to sign in, log in, authenticate, or connect to Aikido. - The user asks to switch Aikido accounts or re-authenticate. Pass `force_reauth: true` so the sign-in flow starts even if a token is already cached. - An earlier Aikido tool returned \"ACTION REQUIRED — Aikido sign-in\" and the user now wants to complete that sign-in. - The user pastes a token they copied from the Aikido sign-in modal (a fallback for when browser couldn't deliver the token automatically). Pass the value verbatim as the `token` argument. NEVER fabricate the `token` value. Only pass it when the user supplies an explicit string they copied from the Aikido UI. REGION - By default, omit `region`. Sign-in automatically redirects the user to their Aikido account's region, so they no longer have to choose one. - Only pass `region` (EU / US / ME / AU) when the user explicitly names a region, or when the automatic redirect sent them to the wrong one. To switch the region of an already signed-in user, pass `force_reauth: true` as well. RESPONSE - If a `token` was passed: a short confirmation that the token was stored, or an error if it didn't look like a valid Aikido token. - If already signed in and `force_reauth` is not set: a short confirmation message. Continue with whatever the user actually wanted. - If sign-in is needed (or `force_reauth` was set): a single sign-in URL plus instructions. The URL contains a one-time `state` token and `redirect_uri` that MUST be passed through verbatim — do not strip query parameters when showing it to the user.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "region": {
        "type": "string",
        "description": "The Aikido region to sign in to. One of: eu, us, me, au (case-insensitive). Omit this in the normal case — sign-in will automatically redirect the user to their account's region. Only set it when the user explicitly names a region, or when the automatic redirect sent them to the wrong one."
      },
      "force_reauth": {
        "type": "boolean",
        "description": "When true, start a new sign-in flow even if the user is already authenticated. Use ONLY when the user explicitly asks to re-authenticate, switch accounts, or sign in again. Do not set this speculatively — it will trigger a browser-based sign-in the user may not want."
      },
      "token": {
        "type": "string",
        "description": "Paste a token here as a manual fallback when the browser-based sign-in could not deliver the token automatically. Do not use this when there is no OS keychain (WSL, headless Linux) — set AIKIDO_API_KEY instead."
      }
    },
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
